"""Printed 249–250: normal and suspension/reflection applications."""
from math12_reviewed_unit1 import heading,paragraph,page
from math12_reviewed_higher_derivatives import eq,note
from math12_native_geometry import geometry,path

def reflection():
 # Exact y²=4px, p=1; rays from focus reflect parallel to the x-axis.
 def pt(x,y):return(100+65*x,165-65*y)
 paths=[path([pt(t*t/4,t) for t in [i/40 for i in range(-85,86)]]),path([pt(0,0),pt(5,0)],dash=True)]
 for y in [-1.8,-1,0,1,1.8]:
  q=pt(y*y/4,y);paths.extend([path([pt(1,0),q]),path([q,pt(4.8,y)],dash=True)])
 return geometry('Figure 9.9','Figure 9.9 — focus rays reflected parallel to the parabola axis',paths,[(155,188,'Focus'),(390,184,'Axis'),(335,40,'Parallel reflected rays →')],points=[{'x':165,'y':165}],size=(490,330))
def bridge():
 def pt(x,y):return(250+x,265-3*y)
 paths=[path([pt(x,10+x*x/1000) for x in range(-200,201,2)]),path([pt(-230,0),pt(230,0)]),path([pt(0,-4),pt(0,62)])]
 for x in [-200,200]:
  paths.append(path([pt(x,0),pt(x,50)],stroke='#64748b'))
  for k in range(-180,181,30):
   if (x<0 and k<0) or (x>0 and k>0):paths.append(path([pt(k,0),pt(k,10+k*k/1000)],stroke='#94a3b8'))
 return geometry('Figure 9.10','Figure 9.10 — 400-foot bridge span, cable 50 feet at towers and 10 feet at its lowest point',paths,[(10,99,'(−200,50)'),(365,99,'(200,50)'),(255,226,'V(0,10)'),(480,281,'x'),(251,74,'y'),(170,306,'Roadway: y=0')],points=[{'x':pt(x,y)[0],'y':pt(x,y)[1]} for x,y in [(-200,50),(0,10),(200,50)]],size=(520,335))
def radar():
 def pt(x,y):return(100+55*x,210-29*y)
 paths=[path([pt(t*t/9,t) for t in [i/20 for i in range(-120,121)]]),path([pt(0,0),pt(5.3,0)]),path([pt(4,-6),pt(4,6)]),path([pt(0,-6.6),pt(4,-6.6)]),path([pt(4.6,-6),pt(4.6,6)])]
 for y in [-5,-3,0,3,5]:q=pt(y*y/9,y);paths.extend([path([pt(4,y),q]),path([q,pt(9/4,0)])])
 return geometry('Figure 9.11','Figure 9.11 — 12-metre radar dish opening and 4-metre depth, focus 9/4 metres from vertex',paths,[(81,235,'V'),(225,239,'F(9/4,0)'),(399,216,'Axis'),(362,135,'6 m'),(362,310,'6 m'),(190,419,'4 m'),(199,21,'y²=9x')],points=[{'x':pt(0,0)[0],'y':pt(0,0)[1]},{'x':pt(9/4,0)[0],'y':pt(9/4,0)[1]}],size=(470,450))
PAGES=[page('129_page_1.jpg',249,[paragraph('Here m₂ is the slope of the normal line to parabola y²=4px at a point p(x₁,y₁), that can be found by differentiating y²=4px with respect to x:'),eq(r'2y\frac{dy}{dx}=4p\quad\Rightarrow\quad\frac{dy}{dx}=\frac{2p}{y}\quad\Rightarrow\quad m_1=\frac{2p}{y_1}\quad\Rightarrow\quad m_2=-\frac1{m_1}=-\frac{y_1}{2p}','28'),paragraph('Substitution of (28) in (27) gives the normal equation:'),eq(r'y-y_1=m_2(x-x_1)'),eq(r'y-y_1=-\frac{y_1}{2p}(x-x_1),\quad m_2=-\frac{y_1}{2p}','29'),heading('Example 7'),paragraph('Find the normal equation at a point p(2,−4) to parabola y²=8x.'),heading('Solution'),paragraph('Result (29) gives the normal line:'),eq(r'y-y_1=-\frac{y_1}{2p}(x-x_1)'),eq(r'y-(-4)=-\frac{-4}{2(2)}(x-2),\quad P(x_1,y_1)=(2,-4),\quad4p=8'),eq(r'y+4=x-2\quad\Rightarrow\quad x-2-y-4=0\quad\Rightarrow\quad x-y-6=0'),heading('(viii) Suspension and reflection problems related to parabola'),paragraph('The parabola is more than just a geometric concept. It has many uses in the physical world listed under:'),paragraph('1. Projectiles in the air, such as a ball, a missile, or water sprayed from a hose, describe a parabolic path when acted on by only gravity.'),paragraph('2. Many arches of bridges or buildings are parabolic in shape. With this shape, the arch can support the structure above it.'),paragraph('3. Rotating a parabola about its line of symmetry creates a bowl type surface called a paraboloid of revolution. A paraboloid has an important reflection property. Any ray or wave that originates at the focus and strikes the surface of the paraboloid is reflected parallel to the line of symmetry. See Figure 9.9.'),reflection(),paragraph('This forms the basic design of the reflectors for automobile headlights, flashlights, searchlights, telescopes, etc. This is also an excellent collecting device and is the basic design of TV, radar and radio antennas.'),heading('Example 8'),paragraph('The cables of a bridge form a parabolic arc. The low point of the cable is 10 ft above the roadway midway between the towers. The distance between the towers is 400 ft. The cable is attached to the towers 50 ft above the roadway. Determine the equation of the parabola that describes the path of the cable. This is shown in Figure 9.10.'),note('For p≠0 the normal formula (29) remains valid at the vertex, giving y=0 even though the intermediate tangent slope is undefined there. Projectile paths are parabolic under constant gravity with nonzero horizontal velocity and negligible resistance. The suspension example assumes the stated parabolic cable model; a freely hanging uniform cable follows a catenary. The reflection diagram reconstructs the mathematical rays and axis of the original lamp illustration.')]),
page('129_page_2.jpg',250,[bridge(),heading('Solution'),paragraph('The parabola is formed by the cable between the two towers. The low point on the cable is midway between the towers and 10 ft above the roadway. Locate the roadway as the x-axis and the line perpendicular to the roadway through the lowest point of the tower as the y-axis. The parabola opens up with vertex (0,10). The other points on the parabola are (200,50) and (−200,50). The standard form is:'),eq(r'(x-h)^2=4p(y-k)','30'),paragraph('The vertex V(0,10) and a point (x,y)=(200,50) are used in (30) to obtain p:'),eq(r'(200-0)^2=4p(50-10),\quad V(h,k)=V(0,10)'),eq(r'40000=160p\quad\Rightarrow\quad p=250'),paragraph('Substitution of V(h,k)=(0,10) and p=250 gives the parabolic equation:'),eq(r'(x-0)^2=4(250)(y-10)'),eq(r'x^2=1000(y-10)\quad\Rightarrow\quad x^2-1000y+10000=0'),paragraph('that describes the path of the cable.'),heading('Example 9'),paragraph('A radar antenna is constructed so that a cross section along its axis is a parabola with the receiver at the focus. Find the focus if the antenna is 12 m across and its depth is 4 m. Find the equation of parabola that described the radar antenna. This is shown in Figure 9.11.'),heading('Solution'),paragraph('The parabola is formed by the radar antenna. Locate the x-axis and y-axis in the xy-plane. The axis of symmetry is the positive x-axis. The parabola opens to the right with vertex V(0,0). The other point on the parabola is (4,6). The standard form is:'),eq(r'y^2=4px'),eq(r'36=4p(4),\quad (x,y)=(4,6)','31'),eq(r'p=\frac{36}{16}=\frac94'),paragraph('The parabolic equation describing the radar antenna is obtained by putting p=9/4 in (31):'),eq(r'y^2=4px=4\left(\frac94\right)x=9x'),paragraph('The focus is F(9/4,0), which is 9/4 m from the vertex V(0,0).'),radar(),note('In Example 8 the y-axis must pass through the midpoint of the span and the lowest point of the cable, rather than the lowest point of a tower as printed. For the physical cable use −200≤x≤200. The radar cross-section has rim points (4,±6); its focus lies 2.25 m from the vertex on the symmetry axis. Ideal incoming rays parallel to the axis reflect to the receiver.')])]
for v in PAGES:v.update(title='CONICS-II',visualStatus='Complete source normal derivation, reflection-ray diagram and exact bridge/radar diagrams',alternateVerification={'pdf':'Math Book for 12 class KPTBB.pdf','pdfPage':129,'side':'left' if v['page']==249 else 'right','reason':'Every printed coefficient, physical dimension and figure inspected visually'})
EXAMPLES=[]
for n,q,steps,ans,pg in [
('7','Find the normal at (2,−4) to y²=8x.',['Check the contact: (−4)²=8·2=16.','Compare y²=8x with y²=4px: p=2.','The tangent slope is 2p/y₁=4/(−4)=−1.','The perpendicular normal slope is −1/(−1)=1.','Use y−(−4)=1(x−2) to obtain y=x−6, or x−y−6=0.','The normal contains (2,−4) and has slope product 1·(−1)=−1 with the tangent, confirming the result.'],'Normal x−y−6=0.',249),
('8','A 400-ft bridge span has a parabolic cable 10 ft above the road at its midpoint and 50 ft at the towers. Find its equation.',['Place the origin on the road midway between towers, so V=(0,10) and tower contacts are (±200,50).','The symmetric upward-opening parabola is x²=4p(y−10).','Substitute (200,50): 40000=4p·40=160p.','Thus p=250 ft, so x²=1000(y−10).','Equivalently y=10+x²/1000 or x²−1000y+10000=0. Use −200≤x≤200 for the cable.','At x=0 the height is 10; at x=±200 it is 50. Both tower heights and the central minimum match the source dimensions.'],'Cable y=10+x²/1000, −200≤x≤200 (feet).',250),
('9','A parabolic radar antenna is 12 m across and 4 m deep. Find its equation and focus.',['Place the vertex at (0,0) with the axis along positive x.','Half the diameter is 6 m, so the rim points are (4,6) and (4,−6).','Write y²=4px and substitute (4,6): 36=16p.','Thus p=9/4 m and the cross-section equation is y²=9x.','The focus is (9/4,0), 2.25 m from the vertex and within the 4-metre depth.','Both rim points satisfy 36=9·4. Ideal rays parallel to the x-axis reflect to this focus, positioning the receiver.'],'y²=9x; focus F(9/4,0), 2.25 m from vertex.',250)]:
 e={'num':n,'title':'Normal and Parabola Applications','question':q,'steps':steps,'answer':ans,'progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'page':pg,'jpg':'129_page_1.jpg' if pg==249 else '129_page_2.jpg','verification':'All physical dimensions, source formulas and contact coordinates checked'}]}
 if n=='8':e['sourceQuestionBlocks']=[bridge()];e['sourceReferences'].insert(0,{'page':249,'jpg':'129_page_1.jpg','verification':'Complete source question checked'})
 if n=='9':e['sourceQuestionBlocks']=[radar()]
 EXAMPLES.append(e)
